24	const basePremiumFor = (type: string): number => {
25	  const basePremium = BASE_PREMIUMS[type];
26	  if (basePremium === undefined) {
27	    throw new Error(`Unknown item type: ${type}`);
28	  }
29	  return basePremium;
30	};
31	
32	const COMPONENT_BLOCK_PREMIUM = 60;
33	const COMPONENT_BLOCK_SIZE = 3;
34	
35	const countByType = (items: Item[]): Map<string, number> => {
36	  const counts = new Map<string, number>();
37	  for (const item of items) {
38	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
39	  }
40	  return counts;
41	};
42	
43	const premiumForGroup = (type: string, count: number): number => {
44	  const basePremium = basePremiumFor(type);
45	  const isComponentBlock =
46	    basePremium === COMPONENT_BASE_PREMIUM && count === COMPONENT_BLOCK_SIZE;
47	  if (isComponentBlock) {
48	    return COMPONENT_BLOCK_PREMIUM;
49	  }
50	  return count * basePremium;
51	};
52	
53	const totalBasePremiumFor = (items: Item[]): number => {
54	  let total = 0;
55	  for (const [type, count] of countByType(items)) {
56	    total += premiumForGroup(type, count);
57	  }
58	  return total;
59	};
60	
61	const surchargeFor = (
62	  items: Item[],
63	  applies: (item: Item) => boolean,
64	  rate: number,
65	): number =>
66	  items
67	    .filter(applies)
68	    .reduce(
69	      (surcharge, item) => surcharge + basePremiumFor(item.type) * rate,
70	      0,
71	    );
72	
73	const CURSE_SURCHARGE_RATE = 0.5;
74	
75	const curseSurchargeFor = (items: Item[]): number =>
76	  surchargeFor(items, (item) => item.cursed === true, CURSE_SURCHARGE_RATE);
77	
78	const ENCHANTMENT_SURCHARGE_RATE = 0.3;
79	
80	const enchantmentSurchargeFor = (items: Item[]): number =>
81	  surchargeFor(items, (item) => item.enchantment !== undefined && item.enchantment >= 5, ENCHANTMENT_SURCHARGE_RATE);
